+#[derive(Clone)]
+struct OAuthClient<C>(C);
+
+impl<C: Client> Client for OAuthClient<C> {
+    type Error = C::Error;
+
+    fn req(
+        &self,
+        mut request: axum::http::Request<Vec<u8>>,
+    ) -> std::pin::Pin<Box<dyn std::future::Future<Output = Result<axum::http::Response<Vec<u8>>, Self::Error>> + Send + '_>> {
+        // This twitch_oauth2 version puts POST credentials in URL parameters.
+        // Send them in the form body, as Twitch documents, to keep them out of URLs.
+        if request.method() == axum::http::Method::POST {
+            if let Some(query) = request.uri().query() {
+                let body = query.as_bytes().to_vec();
+                let mut parts = request.uri().clone().into_parts();
+                parts.path_and_query = Some(request.uri().path().parse().expect("valid request path"));
+                *request.uri_mut() = axum::http::Uri::from_parts(parts).expect("valid OAuth request URI");
+                *request.body_mut() = body;
+                request.headers_mut().insert(axum::http::header::CONTENT_TYPE,
+                    axum::http::HeaderValue::from_static("application/x-www-form-urlencoded"));
+            }
+        }
+        self.0.req(request)
+    }
+}
