+//! Runs the real executable against local OAuth and EventSub servers.
+//! No Twitch account, API key, or external service is used.
+use std::{
+    collections::HashMap,
+    fs,
+    net::SocketAddr,
+    path::{Path, PathBuf},
+    process::{Child, Command, Stdio},
+    sync::{Arc, Mutex},
+    time::{Duration, Instant},
